INSERT INTO plant_photos (
  id, plant_id, household_id, storage_key, content_type, taken_at, is_primary, sort_order
)
SELECT v.id,
       v.plant_id,
       p.household_id,
       p.household_id::text || '/' || v.plant_id::text || '/' || v.id::text || '.jpg',
       'image/jpeg',
       now() - v.days_ago * interval '1 day',
       v.is_primary,
       0
FROM plants p
JOIN (
  VALUES
    ('00000000-0000-0000-0000-000000000300'::uuid, '00000000-0000-0000-0000-000000000200'::uuid, TRUE, 8),
    ('00000000-0000-0000-0000-000000000301'::uuid, '00000000-0000-0000-0000-000000000200'::uuid, FALSE, 22),
